const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

const filePath = path.resolve('/workspace/sandbox/skills/building-accessible-ui/disclosure-widget--framework-react--style-dark/gpt-5.5__s4/index.html');

async function runAxe(page, label) {
  const results = await page.evaluate(async () => await window.axe.run());
  const wcag = results.violations.filter((violation) => !violation.tags.includes('best-practice'));
  if (wcag.length) {
    throw new Error(`${label}: ${JSON.stringify(wcag.map((violation) => ({
      id: violation.id,
      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target),
    })), null, 2)}`);
  }
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 320, height: 720 } });
  await page.goto('file://' + filePath, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  await runAxe(page, 'initial collapsed state');

  const initial = await page.evaluate(() => {
    const buttons = [...document.querySelectorAll('.question-button')];
    const panels = [...document.querySelectorAll('.details')];
    return {
      h1Count: document.querySelectorAll('h1').length,
      examples: document.querySelectorAll('.example').length,
      panels: panels.length,
      collapsed: buttons.every((button) => button.getAttribute('aria-expanded') === 'false') && panels.every((panel) => panel.hidden),
      horizontalOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
    };
  });

  if (initial.h1Count !== 1 || initial.examples !== 5 || initial.panels !== 5 || !initial.collapsed || initial.horizontalOverflow) {
    throw new Error(`initial semantic/state check failed: ${JSON.stringify(initial)}`);
  }

  const buttons = await page.locator('.question-button').count();
  for (let index = 0; index < buttons; index += 1) {
    const button = page.locator('.question-button').nth(index);
    const panel = page.locator('.details').nth(index);
    await button.focus();
    await button.press('Enter');
    if (await button.getAttribute('aria-expanded') !== 'true' || await panel.evaluate((node) => node.hidden)) {
      throw new Error(`button ${index + 1} did not expand with Enter`);
    }
    await runAxe(page, `expanded state ${index + 1}`);
    await button.press('Escape');
    if (await button.getAttribute('aria-expanded') !== 'false' || !(await panel.evaluate((node) => node.hidden))) {
      throw new Error(`button ${index + 1} did not collapse with Escape`);
    }
  }

  await browser.close();
  console.log('PASS axe WCAG violations: 0');
  console.log('PASS disclosure keyboard/state checks');
  console.log('PASS 320px reflow check');
})().catch(async (error) => {
  console.error(error.message);
  process.exit(1);
});
